#include <stdio.h>

/* 以下两次写出「同一个头文件 mymath.h 的内容」，
   第二次靠 include guard（#ifndef/#define/#endif）整段跳过，
   否则 my_add 会被重复定义而编译失败。 */

#ifndef MYMATH_H
#define MYMATH_H
int my_add(int a, int b) { return a + b; }
#endif

/* —— 第二次“包含”同一头文件 —— */
#ifndef MYMATH_H
#define MYMATH_H
int my_add(int a, int b) { return a + b; }
#endif

int main(void) {
    printf("my_add(3,4) = %d（头文件内容写了两次，守卫使第二次整段跳过，未发生重定义）\n",
           my_add(3, 4));
    return 0;
}
